int main() {
    // Solution 1: Extra parentheses (Pre-C++11 fix)
    std::deque<int> c1(
        (std::istream_iterator<int>(std::cin)), 
        (std::istream_iterator<int>()) 
    );

    // Solution 2: Uniform initialization (C++11+)
    std::deque<int> c2{
        std::istream_iterator<int>(std::cin), 
        std::istream_iterator<int>() 
    };
    // The container object is correctly constructed in both cases.
}
